SELECT MIN(result_margin) AS "Minimum Winning First Inning Target"
FROM Matches
WHERE stage IN ('Qualifier 1', 'Qualifier 2', 'Eliminator', 'Final');

SELECT season AS Season, match_date AS "Match Date", venue AS Venue, match_winner AS "Match Winner"
FROM Matches
WHERE (team1 = 'DC' OR team2 = 'DC') AND result_type = 'wickets' AND result_margin = 10;

SELECT MAX(runs_scored) AS "Total Runs Scored"
FROM Deliveries
WHERE batting_team = 'GT';

SELECT match_date AS "Match Date", team1 AS "Team 1", team2 AS "Team 2", result_type AS "Result Type", result_margin AS "Result Margin"
FROM Matches
WHERE season = '2012' AND venue = 'Dharamsala' AND match_winner = 'Punjab';

SELECT match_date AS 'Match Date', team1 AS 'Team 1', team2 AS 'Team 2', result_type AS 'Result Type', result_margin AS 'Result Margin'
FROM Matches
WHERE venue = 'Dharamsala' AND match_date > '2012-12-31' AND match_winner = 'Punjab';

SELECT city AS City, group_concat(DISTINCT venue) AS Venues
FROM Matches
GROUP BY city;

SELECT DISTINCT city AS City, venue AS Venues 
FROM Matches 
ORDER BY City, Venues;

SELECT SUM(runs_scored) AS "Total Runs"
FROM Deliveries
WHERE inning = 1 AND batting_team = 'GT' AND over_number > 10 AND wides = 0 AND noballs = 0;

SELECT AVG(runs_scored) AS "Average Runs" 
FROM Deliveries 
WHERE inning = 1 AND city = 'Ahmedabad';
